"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[17281],{17281:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/crooked-house.png\\"\\n          title=\\"비뚤어진 집\\"\\n          author=\\"애거서 크리스티\\"\\n          publisher=\\"황금가지\\"\\n          publishedDate=\\"2013-05-27\\"\\n          isbn=\\"9788982737084\\"\\n          rating=4\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n살해 동기와 범인이 충격적이었던 작품이다.  \\n쾌감과 통제를 위해 살인을 저지르는 사이코패스적 성향이 나온다.  \\n심지어 이 모든 범행을 수첩에 일기처럼 정리하는 모습에서 오늘날 정의되는 ```사이코패스```에 부합하는 행동으로 보인다.  \\n<br>\\n작품 속 많은 인물들도 범인에 대해 짐작하고 있었으나, 애써 외면하거나 부정하는 모습이 그려진다.  \\n빠르게 눈치챈 독자들은 이 모습에서 조금 답답함을 느꼈을지도 모른다.  \\n<br>\\n마지막에 진실을 알게 된 한 인물의 행동이 인상에 크게 남아 있다."}')}}]);